accuracy_on &lt;- function(model, data) {
  predict(model, new_data = data) |&gt;
    bind_cols(select(data, label)) |&gt;
    accuracy(truth = label, estimate = .pred_class) |&gt;
    pull(.estimate)
}

models &lt;- list(`logistic regression` = m_logit,
               `Naive Bayes` = m_nb, `linear SVM` = m_svm)

tibble(model    = names(models),
       training = map_dbl(models, accuracy_on, train_data),
       test     = map_dbl(models, accuracy_on, test_data)) |&gt;
  pivot_longer(-model, names_to = "set", values_to = "accuracy") |&gt;
  ggplot(aes(accuracy, model, colour = set)) +
  geom_point(size = 4)











The SVM fits its training abstracts best and the test abstracts worst: Part II’s ninth-degree polynomial, on real data



Training accuracy favours the most flexible model. The ranking that counts comes from the test set, the same one for all three.

A classifier on embeddings
